        code: "whoami                    # имя текущего пользователя\nhostname                  # имя машины\npwd                       # текущий каталог (print working directory)\necho \"Привет, $(whoami)\"  # подстановка результата команды в строку",
        explanation: "echo печатает текст; конструкция $(...) выполняет команду и подставляет её вывод — первый шаг к композиции программ.",
